"""Build P2-B2 candidate tasks by executing the deterministic reference tools."""
from __future__ import annotations
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; TOOLS=ROOT/'reference_tools'
sys.path.insert(0,str(TOOLS)); import p2_data_tools as t
OUT=ROOT/'datasets'/'data_qa_candidates.jsonl'
COMMON={'dataset_version':'p1-daily-extract-v1','tool_schema_version':t.TOOL_SCHEMA_VERSION,'numerical_tolerance':1e-6,'duplicate_handling':'statistics deduplicated_exact on six extracted fields; raw query retains provenance','missing_data_handling':'numeric statistics exclude null values and return valid/missing counts'}
